
import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { 
  ArrowLeft, Save, Package, Check, Layers, Search
} from 'lucide-react';
import { useShop } from '../context/ShopContext';
import { useAuth } from '../context/AuthContext';
import { ShopProduct } from '../types';

const BundleEditor: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  // Fixed: methods addItem and updateItem instead of addStoreItem and updateStoreItem
  const { addItem, updateItem, getStoreItem, storeInventory } = useShop();
  const { user } = useAuth();
  
  const [formData, setFormData] = useState<Partial<ShopProduct>>({
    title: '',
    price: 0,
    originalPrice: 0,
    description: '',
    image: '',
    type: 'bundle',
    items: [] 
  });

  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (id) {
      const item = getStoreItem(id);
      if (item && item.type === 'bundle') {
        setFormData(item);
        setSelectedIds(item.items || []);
      }
    }
  }, [id, getStoreItem]);

  const totalValue = storeInventory
    .filter(p => selectedIds.includes(p.id))
    .reduce((acc, curr) => acc + curr.price, 0);

  const toggleSelection = (itemId: string) => {
    if (selectedIds.includes(itemId)) {
      setSelectedIds(selectedIds.filter(i => i !== itemId));
    } else {
      setSelectedIds([...selectedIds, itemId]);
    }
  };

  // Fixed: added async to handle asynchronous addItem/updateItem calls
  const handleSave = async () => {
    const finalData: ShopProduct = {
      id: id || `b_${Date.now()}`,
      authorId: formData.authorId || user?._id,
      title: formData.title || 'Untitled Bundle',
      price: Number(formData.price),
      originalPrice: formData.originalPrice ? Number(formData.originalPrice) : undefined,
      type: 'bundle',
      image: formData.image || 'https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?auto=format&fit=crop&q=80&w=1000',
      rating: formData.rating || 0,
      reviews: formData.reviews || 0,
      tags: ['Bundle', 'Value'],
      description: formData.description || '',
      features: ['All-in-one package', 'Lifetime Updates'],
      items: selectedIds
    };

    if (id) {
      // Fixed: updated method name and added type parameter
      await updateItem('bundle', id, finalData);
    } else {
      // Fixed: updated method name and added type parameter
      await addItem('bundle', finalData);
    }
    navigate('/dashboard');
  };

  const availableItems = storeInventory.filter(
      p => p.id !== id && p.type !== 'bundle' && p.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 pb-20 pt-16">
      <header className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 sticky top-16 z-40">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button onClick={() => navigate('/dashboard')} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-full transition-colors text-slate-500">
              <ArrowLeft size={18} />
            </button>
            <h1 className="text-base md:text-lg font-bold text-slate-900 dark:text-white">
              {id ? 'Edit Bundle' : 'New Bundle'}
            </h1>
          </div>
          <button onClick={handleSave} className="px-4 py-1.5 md:px-6 md:py-2 bg-emerald-600 text-white rounded-lg font-bold text-sm md:text-base hover:bg-emerald-700 transition-colors shadow-lg shadow-emerald-600/20 flex items-center gap-2">
            <Save size={18} /> <span className="hidden sm:inline">Save Bundle</span><span className="sm:hidden">Save</span>
          </button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 py-8 grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
        {/* Left: Bundle Info */}
        <div className="space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-6">
                <h2 className="text-sm font-black uppercase text-slate-400 mb-6 tracking-widest">Bundle Setup</h2>
                
                <div className="space-y-4">
                    <div>
                        <label className="block text-xs font-bold uppercase text-slate-500 mb-1 pl-1">Bundle Title</label>
                        <input type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white font-bold"/>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1 pl-1">Bundle Price ($)</label>
                            <input type="number" value={formData.price} onChange={e => setFormData({...formData, price: Number(e.target.value)})} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white font-bold"/>
                        </div>
                        <div>
                            <label className="block text-xs font-bold uppercase text-slate-500 mb-1 pl-1">Regular Total</label>
                            <div className="w-full px-4 py-3 bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl text-slate-500 font-bold line-through">${totalValue.toFixed(2)}</div>
                        </div>
                    </div>
                    <div>
                        <label className="block text-xs font-bold uppercase text-slate-500 mb-1 pl-1">Cover Image URL</label>
                        <input type="text" value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white text-sm"/>
                    </div>
                    <div>
                        <label className="block text-xs font-bold uppercase text-slate-500 mb-1 pl-1">Description</label>
                        <textarea rows={4} value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 transition-colors dark:text-white text-sm"/>
                    </div>
                </div>
            </div>
        </div>

        {/* Right: Item Selector */}
        <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col lg:h-[calc(100vh-160px)] lg:sticky lg:top-36">
            <h2 className="text-sm font-black uppercase text-slate-400 mb-4 flex justify-between items-center tracking-widest">
                <span>Select Products</span>
                <span className="text-[10px] bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-400 px-2 py-0.5 rounded-full">{selectedIds.length} Added</span>
            </h2>
            
            <div className="relative mb-6">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input type="text" placeholder="Search my inventory..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl outline-none focus:border-emerald-500 dark:text-white text-sm"/>
            </div>

            <div className="flex-1 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                {availableItems.length > 0 ? availableItems.map(item => {
                    const isSelected = selectedIds.includes(item.id);
                    return (
                        <div key={item.id} onClick={() => toggleSelection(item.id)} className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${isSelected ? 'bg-emerald-50 dark:bg-emerald-900/10 border-emerald-500/50' : 'bg-slate-50 dark:bg-slate-950 border-slate-200 dark:border-slate-800 hover:border-emerald-500/30'}`}>
                            <div className={`w-5 h-5 rounded-full border flex items-center justify-center transition-colors ${isSelected ? 'bg-emerald-500 border-emerald-500' : 'border-slate-300 dark:border-slate-600'}`}>
                                {isSelected && <Check size={10} className="text-white" />}
                            </div>
                            <div className="w-10 h-10 bg-slate-200 dark:bg-slate-800 rounded-lg overflow-hidden shrink-0"><img src={item.image} className="w-full h-full object-cover" /></div>
                            <div className="flex-1 min-w-0">
                                <h4 className="font-bold text-slate-900 dark:text-white text-xs truncate">{item.title}</h4>
                                <div className="text-[10px] text-slate-500 uppercase font-black tracking-tighter">${item.price} • {item.type}</div>
                            </div>
                        </div>
                    );
                }) : (
                    <div className="text-center py-10 text-slate-500 text-sm">No items found in your inventory.</div>
                )}
            </div>
        </div>
      </div>
    </div>
  );
};

export default BundleEditor;
